    const double G1_0_1_0_2 = det*c3*c2*c1*w[0][0]*w[0][1]*Jinv_00*Jinv_20 + det*c3*c2*c1*w[0][0]*w[0][1]*Jinv_01*Jinv_21 + det*c3*c2*c1*w[0][0]*w[0][1]*Jinv_02*Jinv_22 + det*c3*c2*c1*w[0][0]*w[0][1]*Jinv_00*Jinv_20 + det*c3*c2*c1*w[0][0]*w[0][1]*Jinv_01*Jinv_21 + det*c3*c2*c1*w[0][0]*w[0][1]*Jinv_02*Jinv_22;
